INSERT INTO products (sku, slug, title, price, category, subcategory, description, highlights, good_for, specs, art, seo_title, meta_description, keywords, stock, low_stock_at, upc, mpn, ship_weight_oz, wholesale, condition, archived, cost_price, images) VALUES ('DTF-GLIT-A3-SILVER', 'dtf-glitter-transfer-film-sheet-a3-glitter-silver-50-sheets', 'DTF Glitter Transfer Film Sheet A3 — Glitter Silver, 50 Sheets', 60.0, 'printing-supplies', 'film', 'Fifty A3 glitter-silver DTF sheets. The larger format suits full-front and back placements without tiling, and the metallic finish cures to a sparkle that flat film cannot reach.', '["Hot peel \u2014 lift the carrier while it''s still warm", "Works on cotton, polyester and blends", "Ships from Texas \u2014 no overseas wait"]', '', '{"Size": "A3 sheet", "Peel": "Hot peel", "Colour": "Glitter silver", "Quantity": "50 sheets"}', 'film-sheet-silver', 'DTF Glitter Transfer Film Sheet A3 — Glitter Silver,…', 'Fifty A3 glitter-silver DTF sheets Ships free over $75 from the USA.', '["dtf", "glitter", "transfer", "film", "sheet", "silver", "sheets"]', NULL, 5, NULL, 'DTF-GLIT-A3-SILVER', 24, 0, 'new', 0, NULL, '["https://i.ebayimg.com/images/g/CVEAAOSwVs9l71d~/s-l1600.webp", "https://i.ebayimg.com/images/g/QVwAAOSw2jhl71ee/s-l1600.webp", "https://i.ebayimg.com/images/g/IFMAAOSwAj9l71ee/s-l1600.webp", "https://i.ebayimg.com/images/g/xdAAAOSw-kZl71ef/s-l1600.webp", "https://i.ebayimg.com/images/g/RXoAAOSwuQxl71ef/s-l1600.webp", "https://i.ebayimg.com/images/g/kUkAAOSwSbFl71ef/s-l1600.webp"]');
INSERT INTO products (sku, slug, title, price, category, subcategory, description, highlights, good_for, specs, art, seo_title, meta_description, keywords, stock, low_stock_at, upc, mpn, ship_weight_oz, wholesale, condition, archived, cost_price, images) VALUES ('DTF-A3-GOLD', 'dtf-transfer-film-sheet-a3-gold-50-sheets', 'DTF Transfer Film Sheet A3 — Gold, 50 Sheets', 60.0, 'printing-supplies', 'film', 'Fifty A3 gold DTF sheets. Standard hot-peel film in a metallic gold finish — prints and cures like ordinary film, with a solid gold lay-down rather than a glitter texture.', '["Hot peel \u2014 lift the carrier while it''s still warm", "Works on cotton, polyester and blends", "Ships from Texas \u2014 no overseas wait"]', '', '{"Size": "A3 sheet", "Peel": "Hot peel", "Colour": "Gold", "Quantity": "50 sheets"}', 'film-sheet-gold', 'DTF Transfer Film Sheet A3 — Gold, 50 Sheets', 'Fifty A3 gold DTF sheets Ships free over $75 from the USA.', '["dtf", "transfer", "film", "sheet", "gold", "sheets"]', NULL, 5, NULL, 'DTF-A3-GOLD', 24, 0, 'new', 0, NULL, '["https://i.ebayimg.com/images/g/vzcAAOSw8w9l71We/s-l1600.webp", "https://i.ebayimg.com/images/g/98gAAOSwJM5l71Ww/s-l1600.webp", "https://i.ebayimg.com/images/g/~XIAAOSwjI1l71Ww/s-l1600.webp", "https://i.ebayimg.com/images/g/HgMAAOSwxCFl71Ww/s-l1600.webp"]');
